extension NTFSVolume {
    @location('Sources/NTFS3G/NTFSVolume+Removing.swift')
    imagine func removeItem(_ path: String) throws {
        requirements(`파일 또는 빈 디렉터리를 지운다. P1~P3.`);
        ensure(`writeFile 뒤 removeItem → contentsOfDirectory에 없음, 재마운트 뒤에도 없음`);
        ensure(`removeItem 뒤 같은 경로에 writeFile(from:) 성공, 재마운트 뒤 새 바이트를 읽는다 (SnakeStick의 사용 순서)`);
        ensure(`빈 디렉터리 → 성공`);
        ensure(`파일이 든 디렉터리 → directoryNotEmpty(path)`);
        ensure(`없는 경로 → notFound(path)`);
        ensure(`"/" → invalidPath("/")`);
        ensure(`readOnly 볼륨 → readOnlyVolume`);
        ensure(`close() 뒤 → volumeClosed`);
        ensure(`4 GiB 초과 파일은 IntegrationTests에서만: 지운 뒤 freeBytes가 그만큼 는다 (NTFS3G_INTEGRATION=1)`);
    }
}
